import pytest

from your_module import group_by  # Replace with the actual module name


def test_group_by_happy_path_groups_by_first_letter_and_preserves_order():
    items = ["apple", "banana", "apricot", "blueberry", "avocado"]

    result = group_by(items, lambda s: s[0])

    assert result == {
        "a": ["apple", "apricot", "avocado"],
        "b": ["banana", "blueberry"],
    }


def test_group_by_empty_list_returns_empty_dict_and_does_not_call_key_fn():
    def key_fn(_):
        pytest.fail("key_fn should not be called for an empty input list")

    assert group_by([], key_fn) == {}


def test_group_by_all_items_same_key():
    items = [1, 2, 3]

    result = group_by(items, lambda _: "same")

    assert result == {"same": [1, 2, 3]}


def test_group_by_allows_none_as_key():
    items = [0, "", False]

    result = group_by(items, lambda _: None)

    assert result == {None: [0, "", False]}


def test_group_by_allows_composite_tuple_keys():
    items = [
        {"kind": "fruit", "color": "red"},
        {"kind": "fruit", "color": "yellow"},
        {"kind": "fruit", "color": "red"},
    ]

    result = group_by(items, lambda item: (item["kind"], item["color"]))

    assert result == {
        ("fruit", "red"): [items[0], items[2]],
        ("fruit", "yellow"): [items[1]],
    }


def test_group_by_items_may_be_unhashable_if_keys_are_hashable():
    items = [[1], [2, 3], [], [4]]

    result = group_by(items, len)

    assert result == {
        1: [[1], [4]],
        2: [[2, 3]],
        0: [[]],
    }


def test_group_by_does_not_mutate_input_list():
    items = [1, 2, 3, 4]
    original = items.copy()

    group_by(items, lambda x: x % 2)

    assert items == original


def test_group_by_propagates_key_fn_exception_and_stops_processing():
    calls = []

    def key_fn(item):
        calls.append(item)
        if item == "bad":
            raise ValueError("bad item")
        return "ok"

    with pytest.raises(ValueError, match="bad item"):
        group_by(["good", "bad", "later"], key_fn)

    assert calls == ["good", "bad"]


def test_group_by_raises_type_error_when_key_is_unhashable():
    items = [1, 2, 3]

    with pytest.raises(TypeError):
        group_by(items, lambda x: [x])


def test_group_by_raises_type_error_when_key_fn_is_not_callable_for_non_empty_input():
    with pytest.raises(TypeError):
        group_by([1], None)


def test_group_by_raises_type_error_when_items_is_not_iterable():
    with pytest.raises(TypeError):
        group_by(None, lambda x: x)
